This is a standard cartesian product that can be built recursively or iteratively.

```python
def cartesian_product(a, b):
    for x in a:
        for y in b:
            if isinstance(x, tuple):
                yield x + (y,)
            else:
                yield (x, y)

def cartesian_product_of_shape(dimentions, result=None):
    if result is None:
        result = [()]
    for dimension in dimentions:
        result = list(cartesian_product(result, range(dimension)))
    return result

def get_numpy_ndarray_rows(obj, shape=None):
    if shape is None:
        shape = obj.shape
    if len(shape) <= 1:
        return
    row_shape = shape[:-1]
    for index in cartesian_product_of_shape(row_shape):
        yield index, obj[index]
```
